static <T> T inTransaction(DataSource ds, Function<Session, T> body) throws SQLException {
    try (var session = ds.openSession()) {        // setup
        try {
            var result = body.apply(session);     // body as a lambda
            session.commit();
            return result;
        } catch (RuntimeException | SQLException e) {
            session.rollback();                   // teardown: failure path
            throw e;
        }
    }
}
